import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Function;

public class SolutionTest {
    public static void main(String[] args) {
        testInvalidArguments();
        testSuccessfulSnapshot();
        testLoaderFailures();
    }

    private static void testInvalidArguments() {
        AtomicInteger calls = new AtomicInteger();
        Function<String, CompletableFuture<List<Solution.Badge>>> loader = key -> {
            calls.incrementAndGet();
            return CompletableFuture.completedFuture(new ArrayList<>());
        };

        assertEmptyUnmodifiable(Solution.loadBadges(null, loader).join());
        assertEmptyUnmodifiable(Solution.loadBadges("   ", loader).join());
        assertEmptyUnmodifiable(Solution.loadBadges("key", null).join());
        assertEquals(0, calls.get());
    }

    private static void testSuccessfulSnapshot() {
        AtomicInteger calls = new AtomicInteger();
        CompletableFuture<List<Solution.Badge>> suppliedFuture = new CompletableFuture<>();
        final String[] receivedKey = new String[1];
        Function<String, CompletableFuture<List<Solution.Badge>>> loader = key -> {
            calls.incrementAndGet();
            receivedKey[0] = key;
            return suppliedFuture;
        };

        CompletableFuture<List<Solution.Badge>> resultFuture =
                Solution.loadBadges("  user-1  ", loader);
        Solution.Badge first = new Solution.Badge("A", "Alpha");
        Solution.Badge duplicate = new Solution.Badge("A", "Alpha");
        List<Solution.Badge> supplied = new ArrayList<>(Arrays.asList(first, duplicate));
        suppliedFuture.complete(supplied);
        List<Solution.Badge> result = resultFuture.join();
        supplied.clear();

        assertEquals(1, calls.get());
        assertEquals("user-1", receivedKey[0]);
        assertEquals(2, result.size());
        assertEquals("A", result.get(0).getCode());
        assertEquals("Alpha", result.get(0).getCaption());
        assertEquals("A", result.get(1).getCode());
        if (result.get(0) == first || result.get(1) == duplicate) {
            throw new AssertionError("badge snapshots were not independent");
        }
        expectThrows(UnsupportedOperationException.class,
                () -> result.add(new Solution.Badge("B", "Beta")));
    }

    private static void testLoaderFailures() {
        assertEmptyUnmodifiable(Solution.loadBadges("x", key -> {
            throw new IllegalStateException("invocation failure");
        }).join());

        assertEmptyUnmodifiable(Solution.loadBadges("x", key -> null).join());

        CompletableFuture<List<Solution.Badge>> failed = new CompletableFuture<>();
        failed.completeExceptionally(new RuntimeException("async failure"));
        assertEmptyUnmodifiable(Solution.loadBadges("x", key -> failed).join());

        assertEmptyUnmodifiable(Solution.loadBadges("x",
                key -> CompletableFuture.completedFuture(null)).join());

        List<Solution.Badge> withNull = new ArrayList<>();
        withNull.add(new Solution.Badge("A", "Alpha"));
        withNull.add(null);
        assertEmptyUnmodifiable(Solution.loadBadges("x",
                key -> CompletableFuture.completedFuture(withNull)).join());
    }

    private static void assertEmptyUnmodifiable(List<Solution.Badge> list) {
        if (list == null || !list.isEmpty()) throw new AssertionError("expected an empty list");
        expectThrows(UnsupportedOperationException.class,
                () -> list.add(new Solution.Badge("X", "X")));
    }

    private static void expectThrows(Class<? extends Throwable> type, Runnable action) {
        try {
            action.run();
        } catch (Throwable thrown) {
            if (type.isInstance(thrown)) return;
            throw new AssertionError("expected " + type.getName() + " but got " + thrown, thrown);
        }
        throw new AssertionError("expected " + type.getName());
    }

    private static void assertEquals(int expected, int actual) {
        if (expected != actual) throw new AssertionError("expected " + expected + " but was " + actual);
    }

    private static void assertEquals(String expected, String actual) {
        if (expected == null ? actual != null : !expected.equals(actual)) {
            throw new AssertionError("expected " + expected + " but was " + actual);
        }
    }
}

